def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        key = event['key']
        rev = event['rev']
        pair = (event['state'], event['stamp'])
        if key not in selected or rev > selected[key][0]:
            selected[key] = (rev, {pair})
        elif rev == selected[key][0]:
            selected[key][1].add(pair)
    result = {}
    for key, (_, pairs) in selected.items():
        if len(pairs) > 1:
            result[key] = 'conflict'
        else:
            state, stamp = next(iter(pairs))
            result[key] = 'stale' if at - stamp > 6 else state
    return result

import json
instance = json.loads('[{"kind":"obs","key":"alder","rev":2,"state":"arrived","stamp":14,"seen":15},{"kind":"obs","key":"alder","rev":2,"state":"missed","stamp":14,"seen":19},{"kind":"obs","key":"balsa","rev":4,"state":"missed","stamp":13,"seen":20},{"kind":"obs","key":"cedar","rev":2,"state":"arrived","stamp":14,"seen":16},{"kind":"obs","key":"cedar","rev":1,"state":"missed","stamp":18,"seen":18},{"kind":"obs","key":"dune","rev":1,"state":"arrived","stamp":19,"seen":21},{"kind":"obs","key":"alder","rev":2,"state":"arrived","stamp":14,"seen":15},{"kind":"obs","key":"balsa","rev":5,"state":"arrived","stamp":19,"seen":30}]')
before = json.dumps(instance)
expected = {'alder':'conflict','balsa':'stale','cedar':'arrived'}
assert audit(instance,20) == expected
assert audit(list(reversed(instance)),20) == expected
assert json.dumps(instance) == before
counterexample = [{'kind':'obs','key':'x','rev':1,'state':'arrived','stamp':14,'seen':15},{'kind':'obs','key':'x','rev':1,'state':'missed','stamp':14,'seen':16}]
assert audit(counterexample,20) == {'x':'conflict'}
assert audit(counterexample[:1],20) == {'x':'arrived'}
assert audit(counterexample[:1],21) == {'x':'stale'}
assert audit([],20) == {}
a = audit(instance,20)
a.clear()
assert audit(instance,20) == expected
print({'result':audit(instance,20),'counterexample_expected':audit(counterexample,20),'checks':'passed'})

